	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/icon-256.png", wrapper.GetIcon256)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/icon-512.png", wrapper.GetIcon512)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/manifest.webmanifest", wrapper.GetManifest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/{$}", wrapper.GetIndex)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/routes/{provider}/{routeId}/{stage}", wrapper.GetRoutePage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/routes/{routeId}/{stage}", wrapper.RedirectLegacyRoutePage)
